forever(function () {
    for (let value of sprites.allOfKind(SpriteKind.Enemy)) {
        if (value.x - mySprite.x > 0) {
            value.vx += -0.5
            if (value.vx > 0) {
                value.vx += -1
            }
        } else {
            value.vx += 0.5
            if (value.vx < 0) {
                value.vx += 1
            }
        }
        if (value.vx > 70) {
            value.vx = 70
        }
        if (value.vx < -70) {
            value.vx = -70
        }
        if (value.y - mySprite.y > 0) {
            value.vy += -0.5
            if (value.vy > 0) {
                value.vy += -1
            }
        } else {
            value.vy += 0.5
            if (value.vy < 0) {
                value.vy += 1
            }
        }
        if (value.vy > 70) {
            value.vy = 70
        }
        if (value.vy < -70) {
            value.vy = -70
        }
    }
})
